function(container, apiUrl, tables) {
  // テスト履歴データのテーブルインデックスを特定
  let testHistoryTableIndex = -1;
  for (let i = 0; i < tables.length; i++) {
    if (tables[i].tableName && tables[i].tableName.includes('テスト履歴')) {
      testHistoryTableIndex = i;
      break;
    }
  }

  // テスト履歴がない場合は適当なテーブルを使用（デモ用）
  if (testHistoryTableIndex === -1) {
    testHistoryTableIndex = 0;
  }

  // 1. テスト履歴再描画関数の定義
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}">
        <td>${r.テスト日時 || r.作成日時 || '-'}</td>
        <td>${r.モデル名 || r.予測モデルバージョン || '-'}</td>
        <td>${r.テスト期間 || '-'}</td>
        <td>${r.対象店舗数 || '1'}</td>
        <td>${r.MAPE || '-'}%</td>
        <td>${r.RMSE || '-'}</td>
        <td>${r.実行時間 || '-'}秒</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id || ''}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データを即座に描画
  renderTestHistory(tables[testHistoryTableIndex]?.records || []);

  // 3. 全店舗選択チェックボックスの処理
  const selectAllStores = container.querySelector("#select-all-stores");
  const storeCheckboxes = container.querySelectorAll('input[name="stores"]');

  selectAllStores.addEventListener("change", function() {
    storeCheckboxes.forEach(cb => {
      cb.checked = this.checked;
    });
  });

  // 4. 全カテゴリ選択チェックボックスの処理
  const selectAllCategories = container.querySelector("#select-all-categories");
  const categoryCheckboxes = container.querySelectorAll('input[name="categories"]');

  selectAllCategories.addEventListener("change", function() {
    categoryCheckboxes.forEach(cb => {
      cb.checked = this.checked;
    });
  });

  // 5. テスト実行ボタンの処理
  container.querySelector("#btn-test-execute").addEventListener("click", async function() {
    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const dataset = container.querySelector('input[name="dataset"]:checked')?.value;
    const selectedStores = Array.from(container.querySelectorAll('input[name="stores"]:checked')).map(cb => cb.value);
    const selectedCategories = Array.from(container.querySelectorAll('input[name="categories"]:checked')).map(cb => cb.value);

    // バリデーション
    if (!model) {
      alert("モデルが選択されていません。モデルを選択してください。");
      return;
    }

    if (!dataset) {
      alert("テストデータセットが選択されていません");
      return;
    }

    if (!startDate || !endDate) {
      alert("テスト期間を設定してください");
      return;
    }

    if (new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を入力してください");
      return;
    }

    if (selectedStores.length === 0) {
      alert("店舗が選択されていません");
      return;
    }

    if (selectedCategories.length === 0) {
      alert("商品カテゴリが未選択です");
      return;
    }

    // 進行状況表示
    const progressDiv = container.querySelector("#test-progress");
    progressDiv.classList.remove("hidden");

    try {
      // テスト実行のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 3000));

      // 結果表示
      const mape = (Math.random() * 15 + 5).toFixed(2);
      const rmse = (Math.random() * 50 + 10).toFixed(2);
      const mae = (Math.random() * 30 + 5).toFixed(2);
      const r2 = (Math.random() * 0.3 + 0.7).toFixed(3);
      const executionTime = (Math.random() * 120 + 30).toFixed(1);

      container.querySelector("#metric-mape").textContent = mape;
      container.querySelector("#metric-rmse").textContent = rmse;
      container.querySelector("#metric-mae").textContent = mae;
      container.querySelector("#metric-r2").textContent = r2;
      container.querySelector("#execution-time").textContent = executionTime;

      // グラフ描画
      drawComparisonChart();

      // モデルパラメータ表示
      updateModelParameters(model);

      // テスト履歴に追加
      const testResult = {
        テスト日時: new Date().toLocaleString(),
        モデル名: model,
        テスト期間: `${startDate} ～ ${endDate}`,
        対象店舗数: selectedStores.length,
        MAPE: mape,
        RMSE: rmse,
        実行時間: executionTime
      };

      const saved = await window.aivicApi.save(testHistoryTableIndex, testResult);
      if (saved) {
        const updatedRows = await window.aivicApi.list(testHistoryTableIndex);
        if (updatedRows) renderTestHistory(updatedRows);
      }

    } catch (error) {
      alert("テスト実行中にエラーが発生しました: " + error.message);
    } finally {
      progressDiv.classList.add("hidden");
    }
  });

  // 6. グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // グラフエリア設定
    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // サンプルデータ生成
    const dataPoints = 30;
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < dataPoints; i++) {
      const base = 100 + Math.sin(i * 0.2) * 30;
      actualData.push(base + (Math.random() - 0.5) * 20);
      predictedData.push(base + (Math.random() - 0.5) * 15);
    }

    // 背景クリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績値線描画
    ctx.strokeStyle = '#3182ce';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (dataPoints - 1)) * chartWidth;
      const y = canvas.height - padding - (actualData[i] / 200) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線描画
    ctx.strokeStyle = '#e53e3e';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (dataPoints - 1)) * chartWidth;
      const y = canvas.height - padding - (predictedData[i] / 200) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#e2e8f0';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績値', padding + 10, padding - 10);
    ctx.fillStyle = '#3182ce';
    ctx.fillRect(padding + 50, padding - 18, 15, 2);

    ctx.fillStyle = '#e2e8f0';
    ctx.fillText('予測値', padding + 80, padding - 10);
    ctx.fillStyle = '#e53e3e';
    ctx.fillRect(padding + 120, padding - 18, 15, 2);
  }

  // 7. モデルパラメータ更新関数
  function updateModelParameters(modelName) {
    const parametersDiv = container.querySelector("#model-parameters");
    const parameters = {
      'model-v1.0': {
        'アルゴリズム': 'LSTM',
        '学習データ期間': '過去24ヶ月',
        'エポック数': '100',
        'バッチサイズ': '32',
        '隠れ層数': '3',
        '正則化': 'L2 (0.001)'
      },
      'model-v1.1': {
        'アルゴリズム': 'LSTM + Attention',
        '学習データ期間': '過去36ヶ月',
        'エポック数': '150',
        'バッチサイズ': '64',
        '隠れ層数': '4',
        '正則化': 'Dropout (0.2)'
      },
      'model-v2.0': {
        'アルゴリズム': 'Transformer',
        '学習データ期間': '過去48ヶ月',
        'エポック数': '200',
        'バッチサイズ': '128',
        '隠れ層数': '6',
        '正則化': 'LayerNorm + Dropout'
      }
    };

    const params = parameters[modelName] || {};
    parametersDiv.innerHTML = Object.entries(params).map(([key, value]) => 
      `<div style="margin-bottom: 8px; color: var(--text);"><strong>${key}:</strong> ${value}</div>`
    ).join('');
  }

  // 8. エクスポートボタンの処理
  container.querySelector("#btn-export").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(testHistoryTableIndex);
    if (!rows) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(row => [
        `"${row.テスト日時 || row.作成日時 || ''}"`,
        `"${row.モデル名 || row.予測モデルバージョン || ''}"`,
        `"${row.テスト期間 || ''}"`,
        row.対象店舗数 || '1',
        row.MAPE || '',
        row.RMSE || '',
        row.実行時間 || ''
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.csv";
    link.click();
  });

  // 9. 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", function(e) {
    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      const testId = detailBtn.dataset.id;
      alert(`テスト詳細画面への遷移 (ID: ${testId})`);
    }
  });
}
